### Resilience4j + Axon + Kafka Integration (Java)

```java
@Service
public class ReplayOrchestrator {
    private final CircuitBreaker cb = CircuitBreaker.ofDefaults("replayCB");
    private final CommandGateway gateway;
    private final KafkaTemplate<String, Event> kafka;
    public ReplayOrchestrator(CommandGateway gateway, KafkaTemplate<String, Event> kafka) {
        this.gateway = gateway; this.kafka = kafka;
    }
    @Retry(name = "replayRetry")
    public void replay(String traceId) {
        Supplier<Void> supplier = CircuitBreaker
            .decorateSupplier(cb, () -> {
                List<Event> events = fetchFromKafka(traceId);
                events.forEach(e -> gateway.send(e));
                return null;
            });
        Try.ofSupplier(supplier).get();
    }
    private List<Event> fetchFromKafka(String traceId) {
        // simplified consumer logic
        return kafka.receive()
            .filter(r -> r.getTraceId().equals(traceId))
            .collectList()
            .block();
    }
}
```

