### Data‑Structure Algorithms (Three Java Solutions)

```java
// 1. Find first duplicate in int[] O(n)
int firstDuplicate(int[] a) {
    Set<Integer> seen = new HashSet<>();
    for (int v : a) if (!seen.add(v)) return v;
    return -1;
}

// 2. Longest substring without repeating chars O(n)
int longestUnique(String s) {
    Map<Character,Integer> map = new HashMap<>();
    int max=0, start=0;
    for (int i=0;i<s.length();i++) {
        char c=s.charAt(i);
        if (map.containsKey(c)) start = Math.max(start, map.get(c)+1);
        map.put(c,i);
        max = Math.max(max, i-start+1);
    }
    return max;
}

// 3. Merge overlapping intervals O(n log n)
List<int[]> merge(List<int[]> iv) {
    iv.sort(Comparator.comparingInt(a->a[0]));
    List<int[]> res = new ArrayList<>();
    for (int[] cur: iv) {
        if (res.isEmpty()||res.get(res.size()-1)[1] < cur[0])
            res.add(cur);
        else
            res.get(res.size()-1)[1] = Math.max(res.get(res.size()-1)[1], cur[1]);
    }
    return res;
}
```

